-- Element — Storage buckets and policies.

-- Private bucket for user files. Size and MIME limits are enforced by Storage
-- itself in addition to the server-side checks (magic bytes, quota, etc.).
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'files',
  'files',
  false,
  10485760,
  array[
    'application/pdf',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'application/vnd.openxmlformats-officedocument.presentationml.presentation',
    'image/jpeg',
    'image/png'
  ]
)
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Public bucket for blog cover images (public content by definition).
-- Only the server (service role) writes to it, after admin checks.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('blog-covers', 'blog-covers', true, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Objects in "files" are readable only by their owner (if the file row is not
-- trashed and the account is active) or by an admin with MFA. There are no
-- insert/update/delete policies: uploads use server-issued signed upload URLs
-- and every other mutation is done by the server with the service role.
create policy files_objects_select on storage.objects
  for select to authenticated
  using (
    bucket_id = 'files'
    and (
      (select public.is_admin())
      or exists (
        select 1 from public.files f
        where f.storage_path = storage.objects.name
          and f.owner_id = (select auth.uid())
          and f.deleted_at is null
          and (select public.is_active_user())
      )
    )
  );

create policy blog_covers_objects_select on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'blog-covers');

-- -----------------------------------------------------------------------------
-- Migration: 20261006000600_scheduled_jobs.sql
-- -----------------------------------------------------------------------------

-- Element — scheduled jobs (pg_cron).
--
-- 1) purge-trash (daily 03:00 UTC): invokes the "purge-trash" Edge Function,
--    which deletes files trashed more than 30 days ago (storage object first,
--    then the database row) and cleans up expired upload intents and their
--    pending objects. Storage objects cannot be deleted from SQL, hence the
--    Edge Function.
--    Required Vault secrets (see README):
--      - purge_trash_url     e.g. https://<project>.supabase.co/functions/v1/purge-trash
--      - purge_trash_secret  same value as the function's PURGE_TRASH_SECRET
--
-- 2) publish-scheduled-posts (every 5 minutes): flips due scheduled posts to
--    'published'. Visibility does not depend on it (RLS already shows due
--    scheduled posts); it keeps the status column accurate.

create or replace function public.invoke_purge_trash()
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_url    text;
  v_secret text;
  v_id     bigint;
begin
  select decrypted_secret into v_url
    from vault.decrypted_secrets where name = 'purge_trash_url';
  select decrypted_secret into v_secret
    from vault.decrypted_secrets where name = 'purge_trash_secret';

  if v_url is null or v_secret is null then
    raise warning 'purge-trash: vault secrets purge_trash_url / purge_trash_secret are not configured';
    return null;
  end if;

  select net.http_post(
    url := v_url,
    body := '{}'::jsonb,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_secret
    ),
    timeout_milliseconds := 55000
  ) into v_id;

  return v_id;
end;
$$;

revoke all on function public.invoke_purge_trash() from public, anon, authenticated, service_role;

create or replace function public.publish_due_posts()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer;
begin
  update public.posts
     set status = 'published'
   where status = 'scheduled' and published_at <= now();
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

revoke all on function public.publish_due_posts() from public, anon, authenticated, service_role;

do $$
begin
  perform cron.unschedule(jobid) from cron.job
   where jobname in ('purge-trash', 'publish-scheduled-posts');
end;
$$;

select cron.schedule('purge-trash', '0 3 * * *', $$select public.invoke_purge_trash();$$);
select cron.schedule('publish-scheduled-posts', '*/5 * * * *', $$select public.publish_due_posts();$$);

-- -----------------------------------------------------------------------------
-- Migration: 20261007000100_hide_quota_from_users.sql
-- -----------------------------------------------------------------------------

-- Element — storage quota and usage are not disclosed to regular users.
-- Quota checks happen server-side (service role); only admins may read them.

-- 1) storage_usage(): admins (with MFA) and the service role only.
create or replace function public.storage_usage(p_owner uuid)
returns table (used_bytes bigint, pending_bytes bigint, quota_bytes bigint)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not (public.is_admin() or (select auth.role()) = 'service_role') then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return query
  select
    coalesce((select sum(f.size_bytes) from public.files f
              where f.owner_id = p_owner and f.deleted_at is null), 0)::bigint,
    coalesce((select sum(i.declared_size) from public.upload_intents i
              where i.owner_id = p_owner and i.consumed_at is null and i.expires_at > now()), 0)::bigint,
    (select p.storage_quota_bytes from public.profiles p where p.id = p_owner);
end;
$$;

-- 2) profiles.storage_quota_bytes: not readable through the API by authenticated
--    sessions (column privileges). Admin screens read it with the service role
--    after requireAdmin().
revoke select on public.profiles from authenticated;
grant select (id, full_name, role, is_active, preferred_locale, created_at) on public.profiles to authenticated;

-- -----------------------------------------------------------------------------
-- Migration: 20261008000100_admin_functions.sql
-- -----------------------------------------------------------------------------

-- Element — admin read models. Every function checks public.is_admin()
-- (active admin + MFA-verified session) before returning anything, and is the
-- only way the API exposes auth emails, sign-in times and storage figures.

-- Escapes LIKE wildcards so user input is matched literally.
create or replace function public.like_escape(p text)
returns text
language sql
immutable
set search_path = ''
as $$
  select replace(replace(replace(p, '\', '\\'), '%', '\%'), '_', '\_');
$$;

-- ---------------------------------------------------------------------------
-- Users list / detail
-- ---------------------------------------------------------------------------
create or replace function public.admin_list_users(
  p_search text default null,
  p_status text default null,   -- 'active' | 'inactive' | 'pending'
  p_role   text default null,   -- 'user' | 'admin'
  p_sort   text default 'created_at',
  p_dir    text default 'desc',
  p_limit  integer default 20,
  p_offset integer default 0,
  p_id     uuid default null
)
returns table (
  id uuid,
  email text,
  full_name text,
  role public.user_role,
  is_active boolean,
  preferred_locale public.app_locale,
  storage_quota_bytes bigint,
  used_bytes bigint,
  file_count bigint,
  created_at timestamptz,
  last_sign_in_at timestamptz,
  invitation_pending boolean,
  has_mfa boolean,
  total_count bigint
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_pattern text := case when nullif(trim(p_search), '') is null then null
                         else '%' || public.like_escape(trim(p_search)) || '%' end;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return query
  with base as (
    select
      p.id,
      u.email::text as email,
      p.full_name,
      p.role,
      p.is_active,
      p.preferred_locale,
      p.storage_quota_bytes,
      coalesce((select sum(f.size_bytes) from public.files f where f.owner_id = p.id and f.deleted_at is null), 0)::bigint as used_bytes,
      (select count(*) from public.files f where f.owner_id = p.id and f.deleted_at is null)::bigint as file_count,
      p.created_at,
      u.last_sign_in_at,
      (u.email_confirmed_at is null) as invitation_pending,
      exists (select 1 from auth.mfa_factors m where m.user_id = p.id and m.status = 'verified') as has_mfa
    from public.profiles p
    join auth.users u on u.id = p.id
    where (p_id is null or p.id = p_id)
      and (v_pattern is null or p.full_name ilike v_pattern or u.email ilike v_pattern)
      and (p_status is null
           or (p_status = 'active' and p.is_active and u.email_confirmed_at is not null)
           or (p_status = 'inactive' and not p.is_active)
           or (p_status = 'pending' and u.email_confirmed_at is null))
      and (p_role is null or p.role::text = p_role)
  )
  select b.*, count(*) over ()::bigint
  from base b
  order by
    case when p_sort = 'full_name' and p_dir = 'asc' then lower(b.full_name) end asc,
    case when p_sort = 'full_name' and p_dir = 'desc' then lower(b.full_name) end desc,
    case when p_sort = 'email' and p_dir = 'asc' then b.email end asc,
    case when p_sort = 'email' and p_dir = 'desc' then b.email end desc,
    case when p_sort = 'last_sign_in_at' and p_dir = 'asc' then b.last_sign_in_at end asc nulls first,
    case when p_sort = 'last_sign_in_at' and p_dir = 'desc' then b.last_sign_in_at end desc nulls last,
    case when p_sort = 'used_bytes' and p_dir = 'asc' then b.used_bytes end asc,
    case when p_sort = 'used_bytes' and p_dir = 'desc' then b.used_bytes end desc,
    case when p_sort = 'created_at' and p_dir = 'asc' then b.created_at end asc,
    b.created_at desc,
    b.id
  limit least(greatest(p_limit, 1), 50000)
  offset greatest(p_offset, 0);
end;
$$;

-- ---------------------------------------------------------------------------
-- Name/email labels for ids (owners, actors) and the owner picker.
-- ---------------------------------------------------------------------------
create or replace function public.admin_user_labels(p_ids uuid[])
returns table (id uuid, full_name text, email text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return query
  select p.id, p.full_name, u.email::text
  from public.profiles p
  join auth.users u on u.id = p.id
  where p.id = any (p_ids);
end;
$$;

create or replace function public.admin_user_options()
returns table (id uuid, full_name text, email text, role public.user_role, is_active boolean)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return query
  select p.id, p.full_name, u.email::text, p.role, p.is_active
  from public.profiles p
  join auth.users u on u.id = p.id
  order by lower(nullif(p.full_name, '')) nulls last, u.email
  limit 5000;
end;
$$;

-- ---------------------------------------------------------------------------
-- Overview totals
-- ---------------------------------------------------------------------------
create or replace function public.admin_overview()
returns table (
  users_total bigint,
  users_active bigint,
  users_inactive bigint,
  users_pending bigint,
  files_active bigint,
  files_trashed bigint,
  storage_used_bytes bigint,
  storage_trashed_bytes bigint,
  uploads_last_7d bigint
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return query
  select
    (select count(*) from public.profiles)::bigint,
    (select count(*) from public.profiles p join auth.users u on u.id = p.id where p.is_active and u.email_confirmed_at is not null)::bigint,
    (select count(*) from public.profiles where not is_active)::bigint,
    (select count(*) from auth.users u join public.profiles p on p.id = u.id where u.email_confirmed_at is null)::bigint,
    (select count(*) from public.files where deleted_at is null)::bigint,
    (select count(*) from public.files where deleted_at is not null)::bigint,
    coalesce((select sum(size_bytes) from public.files where deleted_at is null), 0)::bigint,
    coalesce((select sum(size_bytes) from public.files where deleted_at is not null), 0)::bigint,
    (select count(*) from public.files where created_at > now() - interval '7 days')::bigint;
end;
$$;

-- ---------------------------------------------------------------------------
-- Audit search (free text, action group, actor, subject user, date range).
-- Dates are interpreted in America/Bogota.
-- ---------------------------------------------------------------------------
create or replace function public.admin_search_audit(
  p_q       text default null,
  p_action  text default null,   -- prefix, e.g. 'auth.' or 'file.uploaded'
  p_actor   text default null,   -- matches actor email or name
  p_subject uuid default null,   -- rows where the user is actor or target
  p_from    date default null,
  p_to      date default null,
  p_limit   integer default 50,
  p_offset  integer default 0
)
returns table (
  id bigint,
  created_at timestamptz,
  action text,
  actor_id uuid,
  actor_email text,
  actor_name text,
  target_type text,
  target_id text,
  target_label text,
  metadata jsonb,
  ip inet,
  user_agent text,
  total_count bigint
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := case when nullif(trim(p_q), '') is null then null else '%' || public.like_escape(trim(p_q)) || '%' end;
  v_actor text := case when nullif(trim(p_actor), '') is null then null else '%' || public.like_escape(trim(p_actor)) || '%' end;
  v_action text := case when nullif(trim(p_action), '') is null then null else public.like_escape(trim(p_action)) || '%' end;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return query
  with rows as (
    select
      a.*,
      au.email::text as actor_email,
      ap.full_name as actor_name,
      case a.target_type
        when 'user' then (select tu.email::text from auth.users tu where tu.id::text = a.target_id)
        when 'file' then coalesce((select f.original_name from public.files f where f.id::text = a.target_id), a.metadata ->> 'original_name')
        when 'category' then (select c.name_en || ' / ' || c.name_es from public.file_categories c where c.id::text = a.target_id)
        else null
      end as target_label
    from public.audit_logs a
    left join auth.users au on au.id = a.actor_id
    left join public.profiles ap on ap.id = a.actor_id
    where (v_action is null or a.action like v_action)
      and (p_subject is null or a.actor_id = p_subject or (a.target_type = 'user' and a.target_id = p_subject::text)
           or (a.metadata ->> 'owner_id') = p_subject::text)
      and (p_from is null or a.created_at >= (p_from::timestamp at time zone 'America/Bogota'))
      and (p_to is null or a.created_at < ((p_to + 1)::timestamp at time zone 'America/Bogota'))
      and (v_actor is null or au.email ilike v_actor or ap.full_name ilike v_actor)
  )
  select r.id, r.created_at, r.action, r.actor_id, r.actor_email, r.actor_name, r.target_type, r.target_id,
         r.target_label, r.metadata, r.ip, r.user_agent, count(*) over ()::bigint
  from rows r
  where v_q is null
     or r.action ilike v_q
     or r.target_id ilike v_q
     or r.target_label ilike v_q
     or r.actor_email ilike v_q
     or host(r.ip) ilike v_q
     or r.metadata::text ilike v_q
  order by r.created_at desc, r.id desc
  limit least(greatest(p_limit, 1), 50000)
  offset greatest(p_offset, 0);
end;
$$;

-- ---------------------------------------------------------------------------
-- Category list with usage counts.
-- ---------------------------------------------------------------------------
create or replace function public.admin_list_categories()
returns table (id uuid, name_en text, name_es text, is_archived boolean, created_at timestamptz, file_count bigint)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return query
  select c.id, c.name_en, c.name_es, c.is_archived, c.created_at,
         (select count(*) from public.files f where f.category_id = c.id and f.deleted_at is null)::bigint
  from public.file_categories c
  order by c.is_archived, lower(c.name_en);
end;
$$;

-- Grants: authenticated may call (the functions themselves enforce admin).
do $$
declare
  fn text;
begin
  foreach fn in array array[
    'public.admin_list_users(text, text, text, text, text, integer, integer, uuid)',
    'public.admin_user_labels(uuid[])',
    'public.admin_user_options()',
    'public.admin_overview()',
    'public.admin_search_audit(text, text, text, uuid, date, date, integer, integer)',
    'public.admin_list_categories()'
  ] loop
    execute format('revoke all on function %s from public, anon', fn);
    execute format('grant execute on function %s to authenticated, service_role', fn);
  end loop;
end;
$$;

-- Category names are unique per language (case-insensitive) to avoid confusing filters.
create unique index file_categories_name_en_key on public.file_categories (lower(name_en));
create unique index file_categories_name_es_key on public.file_categories (lower(name_es));

-- -----------------------------------------------------------------------------
-- Migration: 20261008000200_session_validity.sql
-- -----------------------------------------------------------------------------

-- Element — immediate session revocation.
-- Access tokens stay cryptographically valid until they expire (jwt_expiry).
-- session_context() now also reports whether the token's session still exists,
-- so revoked sessions (deactivation, forced password reset, "sign out other
-- sessions" after a password change) lose access on their very next request.

drop function if exists public.session_context();

create function public.session_context()
returns table (
  role public.user_role,
  is_active boolean,
  preferred_locale public.app_locale,
  full_name text,
  has_verified_mfa boolean,
  session_valid boolean
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    p.role,
    p.is_active,
    p.preferred_locale,
    p.full_name,
    exists (
      select 1 from auth.mfa_factors f
      where f.user_id = p.id and f.status = 'verified' and f.factor_type = 'totp'
    ),
    exists (
      select 1 from auth.sessions s
      where s.id = nullif((select auth.jwt()) ->> 'session_id', '')::uuid
        and s.user_id = p.id
    )
  from public.profiles p
  where p.id = (select auth.uid());
$$;

revoke all on function public.session_context() from public, anon;
grant execute on function public.session_context() to authenticated;

-- -----------------------------------------------------------------------------
-- Migration: 20261008000300_rls_session_check.sql
-- -----------------------------------------------------------------------------

-- Element — RLS helpers also require the token's session to still exist, so a
-- revoked session cannot keep using the Data/Storage APIs directly until its
-- access token expires. (Lookup by primary key: negligible cost.)

create or replace function public.current_session_valid()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from auth.sessions s
    where s.id = nullif((select auth.jwt()) ->> 'session_id', '')::uuid
      and s.user_id = (select auth.uid())
  );
$$;

revoke all on function public.current_session_valid() from public, anon;
grant execute on function public.current_session_valid() to authenticated, service_role;

create or replace function public.is_active_user()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.profiles p
    where p.id = (select auth.uid()) and p.is_active
  ) and public.current_session_valid();
$$;

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select auth.jwt() ->> 'aal') = 'aal2', false)
     and exists (
       select 1 from public.profiles p
       where p.id = (select auth.uid()) and p.is_active and p.role = 'admin'
     )
     and public.current_session_valid();
$$;

-- -----------------------------------------------------------------------------
-- Migration: 20261009000100_blog_public.sql
-- -----------------------------------------------------------------------------

-- Element — public blog read model.
-- SECURITY INVOKER functions (RLS still applies) that ALSO filter visibility
-- explicitly, so signed-in admins browsing the public site never see drafts or
-- future scheduled posts. A post appears in a locale only if it has a
-- translation for that locale.

create or replace function public.post_is_visible(p_status public.post_status, p_published_at timestamptz)
returns boolean
language sql
stable
set search_path = ''
as $$
  select p_status = 'published' or (p_status = 'scheduled' and p_published_at <= now());
$$;

-- Listing with optional category (slug in either language) and pagination.
create or replace function public.blog_list(
  p_locale public.app_locale,
  p_category text default null,
  p_limit integer default 9,
  p_offset integer default 0
)
returns table (
  post_id uuid,
  title text,
  slug text,
  excerpt text,
  cover_path text,
  published_at timestamptz,
  category_name text,
  category_slug text,
  total_count bigint
)
language sql
stable
security invoker
set search_path = ''
as $$
  select
    p.id,
    t.title,
    t.slug,
    t.excerpt,
    p.cover_path,
    p.published_at,
    case when p_locale = 'es' then c.name_es else c.name_en end,
    case when p_locale = 'es' then c.slug_es else c.slug_en end,
    count(*) over ()
  from public.posts p
  join public.post_translations t on t.post_id = p.id and t.locale = p_locale
  left join public.post_categories c on c.id = p.category_id
  where public.post_is_visible(p.status, p.published_at)
    and (p_category is null or c.slug_en = p_category or c.slug_es = p_category)
  order by p.published_at desc, p.id
  limit least(greatest(p_limit, 1), 100)
  offset greatest(p_offset, 0);
$$;

-- Single post by slug. The slug may belong to any locale (e.g. after a language
-- switch); the requested locale's translation is returned when it exists
-- (title is null otherwise). `slugs` maps each available locale to its slug.
create or replace function public.blog_post(p_locale public.app_locale, p_slug text)
returns table (
  post_id uuid,
  title text,
  slug text,
  excerpt text,
  content text,
  cover_path text,
  published_at timestamptz,
  updated_at timestamptz,
  category_name text,
  category_slug text,
  slugs jsonb
)
language sql
stable
security invoker
set search_path = ''
as $$
  with target as (
    select t0.post_id
    from public.post_translations t0
    join public.posts p0 on p0.id = t0.post_id
    where t0.slug = p_slug and public.post_is_visible(p0.status, p0.published_at)
    order by (t0.locale = p_locale) desc
    limit 1
  )
  select
    p.id,
    t.title,
    t.slug,
    t.excerpt,
    t.content,
    p.cover_path,
    p.published_at,
    greatest(p.updated_at, coalesce(t.updated_at, p.updated_at)),
    case when p_locale = 'es' then c.name_es else c.name_en end,
    case when p_locale = 'es' then c.slug_es else c.slug_en end,
    (select jsonb_object_agg(t2.locale, t2.slug) from public.post_translations t2 where t2.post_id = p.id)
  from target
  join public.posts p on p.id = target.post_id
  left join public.post_translations t on t.post_id = p.id and t.locale = p_locale
  left join public.post_categories c on c.id = p.category_id;
$$;

-- Categories that have at least one visible post in the locale.
create or replace function public.blog_categories(p_locale public.app_locale)
returns table (name text, slug text, post_count bigint)
language sql
stable
security invoker
set search_path = ''
as $$
  select
    case when p_locale = 'es' then c.name_es else c.name_en end,
    case when p_locale = 'es' then c.slug_es else c.slug_en end,
    count(*)
  from public.post_categories c
  join public.posts p on p.category_id = c.id
  join public.post_translations t on t.post_id = p.id and t.locale = p_locale
  where public.post_is_visible(p.status, p.published_at)
  group by c.id, c.name_en, c.name_es, c.slug_en, c.slug_es
  order by 1;
$$;

-- Sitemap entries for every visible post.
create or replace function public.blog_sitemap()
returns table (post_id uuid, slugs jsonb, updated_at timestamptz)
language sql
stable
security invoker
set search_path = ''
as $$
  select p.id, jsonb_object_agg(t.locale, t.slug), max(greatest(p.updated_at, t.updated_at))
  from public.posts p
  join public.post_translations t on t.post_id = p.id
  where public.post_is_visible(p.status, p.published_at)
  group by p.id;
$$;

grant execute on function public.post_is_visible(public.post_status, timestamptz) to anon, authenticated;
grant execute on function public.blog_list(public.app_locale, text, integer, integer) to anon, authenticated;
grant execute on function public.blog_post(public.app_locale, text) to anon, authenticated;
grant execute on function public.blog_categories(public.app_locale) to anon, authenticated;
grant execute on function public.blog_sitemap() to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Audit labels for posts, post categories and contact messages.
-- ---------------------------------------------------------------------------
create or replace function public.admin_search_audit(
  p_q       text default null,
  p_action  text default null,
  p_actor   text default null,
  p_subject uuid default null,
  p_from    date default null,
  p_to      date default null,
  p_limit   integer default 50,
  p_offset  integer default 0
)
returns table (
  id bigint,
  created_at timestamptz,
  action text,
  actor_id uuid,
  actor_email text,
  actor_name text,
  target_type text,
  target_id text,
  target_label text,
  metadata jsonb,
  ip inet,
  user_agent text,
  total_count bigint
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := case when nullif(trim(p_q), '') is null then null else '%' || public.like_escape(trim(p_q)) || '%' end;
  v_actor text := case when nullif(trim(p_actor), '') is null then null else '%' || public.like_escape(trim(p_actor)) || '%' end;
  v_action text := case when nullif(trim(p_action), '') is null then null else public.like_escape(trim(p_action)) || '%' end;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return query
  with rows as (
    select
      a.*,
      au.email::text as actor_email,
      ap.full_name as actor_name,
      case a.target_type
        when 'user' then (select tu.email::text from auth.users tu where tu.id::text = a.target_id)
        when 'file' then coalesce((select f.original_name from public.files f where f.id::text = a.target_id), a.metadata ->> 'original_name')
        when 'category' then (select c.name_en || ' / ' || c.name_es from public.file_categories c where c.id::text = a.target_id)
        when 'post' then coalesce(
          (select string_agg(pt.title, ' / ' order by pt.locale) from public.post_translations pt where pt.post_id::text = a.target_id),
          a.metadata ->> 'title')
        when 'post_category' then coalesce(
          (select pc.name_en || ' / ' || pc.name_es from public.post_categories pc where pc.id::text = a.target_id),
          a.metadata ->> 'name')
        when 'contact' then (select cm.subject from public.contact_messages cm where cm.id::text = a.target_id)
        else null
      end as target_label
    from public.audit_logs a
    left join auth.users au on au.id = a.actor_id
    left join public.profiles ap on ap.id = a.actor_id
    where (v_action is null or a.action like v_action)
      and (p_subject is null or a.actor_id = p_subject or (a.target_type = 'user' and a.target_id = p_subject::text)
           or (a.metadata ->> 'owner_id') = p_subject::text)
      and (p_from is null or a.created_at >= (p_from::timestamp at time zone 'America/Bogota'))
      and (p_to is null or a.created_at < ((p_to + 1)::timestamp at time zone 'America/Bogota'))
      and (v_actor is null or au.email ilike v_actor or ap.full_name ilike v_actor)
  )
  select r.id, r.created_at, r.action, r.actor_id, r.actor_email, r.actor_name, r.target_type, r.target_id,
         r.target_label, r.metadata, r.ip, r.user_agent, count(*) over ()::bigint
  from rows r
  where v_q is null
     or r.action ilike v_q
     or r.target_id ilike v_q
     or r.target_label ilike v_q
     or r.actor_email ilike v_q
     or host(r.ip) ilike v_q
     or r.metadata::text ilike v_q
  order by r.created_at desc, r.id desc
  limit least(greatest(p_limit, 1), 50000)
  offset greatest(p_offset, 0);
end;
$$;

-- -----------------------------------------------------------------------------
-- Migration: 20261009000200_admin_save_post.sql
-- -----------------------------------------------------------------------------

-- Element — atomic save of a post and its translations.
-- SECURITY INVOKER: runs with the caller's privileges, so the admin RLS
-- policies (is_admin(): active admin + MFA session) govern every write.
-- Any failure (e.g. a duplicate slug) rolls back the whole save.
--
-- p_translations: {"en": {"title","slug","excerpt","content"}, "es": {...}}.
-- Locales absent from the payload are removed (the translation was emptied).

create or replace function public.admin_save_post(
  p_status public.post_status,
  p_translations jsonb,
  p_id uuid default null,
  p_published_at timestamptz default null,
  p_category_id uuid default null
)
returns uuid
language plpgsql
volatile
security invoker
set search_path = ''
as $$
declare
  v_id uuid := p_id;
  v_locale text;
  v_t jsonb;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if jsonb_typeof(p_translations) <> 'object' or (select count(*) from jsonb_object_keys(p_translations)) = 0 then
    raise exception 'translation_required' using errcode = '22023';
  end if;

  if v_id is null then
    insert into public.posts (status, published_at, category_id, author_id)
    values (p_status, p_published_at, p_category_id, (select auth.uid()))
    returning id into v_id;
  else
    update public.posts
       set status = p_status, published_at = p_published_at, category_id = p_category_id
     where id = v_id;
    if not found then
      raise exception 'not_found' using errcode = 'P0002';
    end if;
  end if;

  delete from public.post_translations
   where post_id = v_id and not (p_translations ? locale::text);

  for v_locale, v_t in select key, value from jsonb_each(p_translations) loop
    insert into public.post_translations (post_id, locale, title, slug, excerpt, content)
    values (
      v_id,
      v_locale::public.app_locale,
      v_t ->> 'title',
      v_t ->> 'slug',
      coalesce(v_t ->> 'excerpt', ''),
      coalesce(v_t ->> 'content', '')
    )
    on conflict (post_id, locale) do update
      set title = excluded.title,
          slug = excluded.slug,
          excerpt = excluded.excerpt,
          content = excluded.content;
  end loop;

  -- Touch the post so updated_at reflects translation edits too.
  update public.posts set updated_at = now() where id = v_id;
  return v_id;
end;
$$;

revoke all on function public.admin_save_post(public.post_status, jsonb, uuid, timestamptz, uuid) from public, anon;
grant execute on function public.admin_save_post(public.post_status, jsonb, uuid, timestamptz, uuid) to authenticated;

-- -----------------------------------------------------------------------------
-- Migration: 20261010000100_mfa_recovery_codes.sql
-- -----------------------------------------------------------------------------

-- Element — MFA recovery codes.
-- Supabase Auth has no native recovery codes. Ten single-use codes are issued
-- when TOTP is enrolled (or regenerated with a valid TOTP code). Only a keyed
-- hash (HMAC-SHA256 with a server-side secret) is stored; plaintext codes are
-- shown to the user exactly once. All writes are done by the server with the
-- service role; users can only learn how many unused codes they have left.

create table public.mfa_recovery_codes (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles (id) on delete cascade,
  code_hash  text not null check (code_hash ~ '^[a-f0-9]{64}$'),
  used_at    timestamptz,
  created_at timestamptz not null default now(),
  constraint mfa_recovery_codes_user_hash_key unique (user_id, code_hash)
);

create index mfa_recovery_codes_user_unused_idx on public.mfa_recovery_codes (user_id) where used_at is null;

alter table public.mfa_recovery_codes enable row level security;
revoke all on public.mfa_recovery_codes from anon, authenticated;

-- Admins (with MFA) may see that codes exist for a user; nobody reads hashes
-- through the API (no column grant on code_hash).
grant select (id, user_id, used_at, created_at) on public.mfa_recovery_codes to authenticated;

create policy mfa_recovery_codes_select_own on public.mfa_recovery_codes
  for select to authenticated
  using (user_id = (select auth.uid()) and (select public.is_active_user()));

create policy mfa_recovery_codes_select_admin on public.mfa_recovery_codes
  for select to authenticated
  using ((select public.is_admin()));

-- Remaining unused codes for the signed-in user (profile page).
create or replace function public.my_recovery_codes_remaining()
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)::integer
  from public.mfa_recovery_codes c
  where c.user_id = (select auth.uid()) and c.used_at is null and public.is_active_user();
$$;

revoke all on function public.my_recovery_codes_remaining() from public, anon;
grant execute on function public.my_recovery_codes_remaining() to authenticated;

-- Atomically consumes one unused code (service role only). Returns true if a
-- matching unused code existed.
create or replace function public.consume_recovery_code(p_user uuid, p_hash text)
returns boolean
language sql
volatile
security definer
set search_path = ''
as $$
  with used as (
    update public.mfa_recovery_codes
       set used_at = now()
     where user_id = p_user and code_hash = p_hash and used_at is null
    returning id
  )
  select exists (select 1 from used);
$$;

revoke all on function public.consume_recovery_code(uuid, text) from public, anon, authenticated;
grant execute on function public.consume_recovery_code(uuid, text) to service_role;

-- -----------------------------------------------------------------------------
-- Migration: 20261011000100_self_signup_upload_access.sql
-- -----------------------------------------------------------------------------

-- Element — open sign-up (email link or Google) with admin-controlled upload access.
--
-- Anyone may create an account, but only accounts with profiles.can_upload may
-- upload documents. An administrator grants it to an existing account, or
-- pre-authorizes an email address that has no account yet (upload_grants): the
-- grant is applied when that address is verified (email link confirmed, or
-- first sign-in with Google), never before, so nobody can claim it with an
-- address they do not control.

-- ---------------------------------------------------------------------------
-- profiles.can_upload. Accounts that already exist were invited by an admin
-- and keep the access they had.
-- ---------------------------------------------------------------------------
alter table public.profiles add column can_upload boolean not null default false;
update public.profiles set can_upload = true;

grant select (can_upload) on public.profiles to authenticated;

-- ---------------------------------------------------------------------------
-- Pre-authorized addresses (pending until an account with that address is verified).
-- ---------------------------------------------------------------------------
create table public.upload_grants (
  email      text primary key check (email = lower(email) and char_length(email) between 3 and 254),
  granted_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now()
);

alter table public.upload_grants enable row level security;
revoke all on public.upload_grants from anon, authenticated;
grant select, insert, delete on public.upload_grants to authenticated;

create policy upload_grants_select_admin on public.upload_grants
  for select to authenticated
  using ((select public.is_admin()));

create policy upload_grants_insert_admin on public.upload_grants
  for insert to authenticated
  with check ((select public.is_admin()) and granted_by = (select auth.uid()));

create policy upload_grants_delete_admin on public.upload_grants
  for delete to authenticated
  using ((select public.is_admin()));

-- Applies (and consumes) a pending grant once the account's address is verified.
-- Fires after on_auth_user_created (triggers run in name order), so the profile exists.
create or replace function public.apply_upload_grant()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.email_confirmed_at is not null and new.email is not null then
    with consumed as (
      delete from public.upload_grants g where g.email = lower(new.email) returning 1
    )
    update public.profiles p
       set can_upload = true
     where p.id = new.id and exists (select 1 from consumed);
  end if;
  return new;
end;
$$;

create trigger on_auth_user_upload_grant
  after insert or update of email_confirmed_at on auth.users
  for each row execute function public.apply_upload_grant();

-- ---------------------------------------------------------------------------
-- Regular users cannot grant themselves upload access.
-- ---------------------------------------------------------------------------
create or replace function public.protect_profile_columns()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.id is distinct from old.id or new.created_at is distinct from old.created_at then
    raise exception 'immutable_column' using errcode = '42501';
  end if;

  if current_user in ('authenticated', 'anon') then
    if not public.is_admin() then
      if new.role is distinct from old.role
         or new.is_active is distinct from old.is_active
         or new.storage_quota_bytes is distinct from old.storage_quota_bytes
         or new.can_upload is distinct from old.can_upload then
        raise exception 'forbidden_column' using errcode = '42501';
      end if;
    elsif old.id = (select auth.uid())
          and (new.role is distinct from old.role or new.is_active is distinct from old.is_active) then
      raise exception 'self_privilege_change' using errcode = '42501';
    end if;
  end if;

  if old.role = 'admin' and old.is_active
     and (new.role <> 'admin' or not new.is_active)
     and not exists (
       select 1 from public.profiles p
       where p.role = 'admin' and p.is_active and p.id <> old.id
     ) then
    raise exception 'last_admin' using errcode = '42501';
  end if;

  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- session_context() also reports can_upload.
-- ---------------------------------------------------------------------------
drop function if exists public.session_context();

create function public.session_context()
returns table (
  role public.user_role,
  is_active boolean,
  preferred_locale public.app_locale,
  full_name text,
  has_verified_mfa boolean,
  session_valid boolean,
  can_upload boolean
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    p.role,
    p.is_active,
    p.preferred_locale,
    p.full_name,
    exists (
      select 1 from auth.mfa_factors f
      where f.user_id = p.id and f.status = 'verified' and f.factor_type = 'totp'
    ),
    exists (
      select 1 from auth.sessions s
      where s.id = nullif((select auth.jwt()) ->> 'session_id', '')::uuid
        and s.user_id = p.id
    ),
    p.can_upload
  from public.profiles p
  where p.id = (select auth.uid());
$$;

revoke all on function public.session_context() from public, anon;
grant execute on function public.session_context() to authenticated;

-- ---------------------------------------------------------------------------
-- admin_list_users(): can_upload column and filter (p_upload: 'yes' | 'no').
-- ---------------------------------------------------------------------------
drop function if exists public.admin_list_users(text, text, text, text, text, integer, integer, uuid);

create function public.admin_list_users(
  p_search text default null,
  p_status text default null,   -- 'active' | 'inactive' | 'pending'
  p_role   text default null,   -- 'user' | 'admin'
  p_sort   text default 'created_at',
  p_dir    text default 'desc',
  p_limit  integer default 20,
  p_offset integer default 0,
  p_id     uuid default null,
  p_upload text default null    -- 'yes' | 'no'
)
returns table (
  id uuid,
  email text,
  full_name text,
  role public.user_role,
  is_active boolean,
  preferred_locale public.app_locale,
  storage_quota_bytes bigint,
  used_bytes bigint,
  file_count bigint,
  created_at timestamptz,
  last_sign_in_at timestamptz,
  invitation_pending boolean,
  has_mfa boolean,
  can_upload boolean,
  total_count bigint
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_pattern text := case when nullif(trim(p_search), '') is null then null
                         else '%' || public.like_escape(trim(p_search)) || '%' end;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return query
  with base as (
    select
      p.id,
      u.email::text as email,
      p.full_name,
      p.role,
      p.is_active,
      p.preferred_locale,
      p.storage_quota_bytes,
      coalesce((select sum(f.size_bytes) from public.files f where f.owner_id = p.id and f.deleted_at is null), 0)::bigint as used_bytes,
      (select count(*) from public.files f where f.owner_id = p.id and f.deleted_at is null)::bigint as file_count,
      p.created_at,
      u.last_sign_in_at,
      (u.email_confirmed_at is null) as invitation_pending,
      exists (select 1 from auth.mfa_factors m where m.user_id = p.id and m.status = 'verified') as has_mfa,
      p.can_upload
    from public.profiles p
    join auth.users u on u.id = p.id
    where (p_id is null or p.id = p_id)
      and (v_pattern is null or p.full_name ilike v_pattern or u.email ilike v_pattern)
      and (p_status is null
           or (p_status = 'active' and p.is_active and u.email_confirmed_at is not null)
           or (p_status = 'inactive' and not p.is_active)
           or (p_status = 'pending' and u.email_confirmed_at is null))
      and (p_role is null or p.role::text = p_role)
      and (p_upload is null or (p_upload = 'yes') = p.can_upload)
  )
  select b.*, count(*) over ()::bigint
  from base b
  order by
    case when p_sort = 'full_name' and p_dir = 'asc' then lower(b.full_name) end asc,
    case when p_sort = 'full_name' and p_dir = 'desc' then lower(b.full_name) end desc,
    case when p_sort = 'email' and p_dir = 'asc' then b.email end asc,
    case when p_sort = 'email' and p_dir = 'desc' then b.email end desc,
    case when p_sort = 'last_sign_in_at' and p_dir = 'asc' then b.last_sign_in_at end asc nulls first,
    case when p_sort = 'last_sign_in_at' and p_dir = 'desc' then b.last_sign_in_at end desc nulls last,
    case when p_sort = 'used_bytes' and p_dir = 'asc' then b.used_bytes end asc,
    case when p_sort = 'used_bytes' and p_dir = 'desc' then b.used_bytes end desc,
    case when p_sort = 'created_at' and p_dir = 'asc' then b.created_at end asc,
    b.created_at desc,
    b.id
  limit least(greatest(p_limit, 1), 50000)
  offset greatest(p_offset, 0);
end;
$$;

revoke all on function public.admin_list_users(text, text, text, text, text, integer, integer, uuid, text) from public, anon;
grant execute on function public.admin_list_users(text, text, text, text, text, integer, integer, uuid, text) to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- Migration: 20261013000100_site_settings_and_blog_types.sql
-- -----------------------------------------------------------------------------

-- Element — editable business details and richer blog posts.
--
-- 1) site_settings: a single row with the contact details, location, opening
--    hours and the top announcement bar, editable by admins from the panel and
--    readable by everyone (it is public information shown on the site).
-- 2) posts: kind (article or quick update), featured flag and official source.
--    New read/write functions (blog_feed, blog_article, admin_save_post_v2) are
--    added next to the existing ones, so the application keeps working while
--    this migration is pending.

-- ---------------------------------------------------------------------------
-- site_settings (singleton row: id is always true)
-- ---------------------------------------------------------------------------
create table public.site_settings (
  id                     boolean primary key default true check (id),
  phone                  text not null default '' check (char_length(phone) <= 40),
  whatsapp               text not null default '' check (whatsapp ~ '^[0-9]{0,15}$'),
  email                  text not null default '' check (char_length(email) <= 254),
  address                text not null default '' check (char_length(address) <= 300),
  maps_url               text not null default '' check (maps_url = '' or (maps_url ~ '^https://' and char_length(maps_url) <= 1000)),
  booking_url            text not null default '' check (booking_url = '' or (booking_url ~ '^https://' and char_length(booking_url) <= 1000)),
  hours_regular_es       text not null default '' check (char_length(hours_regular_es) <= 1000),
  hours_regular_en       text not null default '' check (char_length(hours_regular_en) <= 1000),
  hours_season_es        text not null default '' check (char_length(hours_season_es) <= 1000),
  hours_season_en        text not null default '' check (char_length(hours_season_en) <= 1000),
  announcement_enabled   boolean not null default true,
  announcement_label_es  text not null default '' check (char_length(announcement_label_es) <= 40),
  announcement_label_en  text not null default '' check (char_length(announcement_label_en) <= 40),
  announcement_text_es   text not null default '' check (char_length(announcement_text_es) <= 200),
  announcement_text_en   text not null default '' check (char_length(announcement_text_en) <= 200),
  updated_by             uuid references public.profiles (id) on delete set null,
  updated_at             timestamptz not null default now()
);

create trigger site_settings_set_updated_at
  before update on public.site_settings
  for each row execute function public.set_updated_at();

insert into public.site_settings (
  phone, whatsapp, email, address,
  hours_regular_es, hours_regular_en, hours_season_es, hours_season_en,
  announcement_label_es, announcement_label_en, announcement_text_es, announcement_text_en
) values (
  '+1 (917) 890-0892', '19178900892', '', '',
  E'Lun – Vie · 10:00 a. m. – 6:00 p. m.\nSábados · con cita\nDomingos · cerrado',
  E'Mon – Fri · 10:00 a.m. – 6:00 p.m.\nSaturday · by appointment\nSunday · closed',
  E'Lun – Sáb · 9:00 a. m. – 8:00 p. m.\nDomingos · con cita',
  E'Mon – Sat · 9:00 a.m. – 8:00 p.m.\nSunday · by appointment',
  '15 OCT', 'OCT 15',
  '¿Pediste extensión? Te ayudamos a presentar tu declaración a tiempo.',
  'Filed an extension? We''ll help you file your return on time.'
);

alter table public.site_settings enable row level security;

create policy site_settings_select_public on public.site_settings
  for select to anon, authenticated
  using (true);

create policy site_settings_update_admin on public.site_settings
  for update to authenticated
  using ((select public.is_admin()))
  with check ((select public.is_admin()));

-- No insert/delete for anyone but the service role: the row always exists.
revoke insert, delete, truncate on public.site_settings from anon, authenticated;
grant select on public.site_settings to anon, authenticated;
grant update on public.site_settings to authenticated;

-- ---------------------------------------------------------------------------
-- posts: kind, featured, official source
-- ---------------------------------------------------------------------------
create type public.post_kind as enum ('article', 'update');

alter table public.posts
  add column kind        public.post_kind not null default 'article',
  add column is_featured boolean not null default false,
  add column source_url  text check (source_url is null or (source_url ~ '^https://' and char_length(source_url) <= 1000));

-- At most one featured post.
create unique index posts_single_featured_idx on public.posts (is_featured) where is_featured;

-- Estimated reading time from the stored HTML (about 1,100 characters a minute).
create or replace function public.reading_minutes(p_html text)
returns integer
language sql
immutable
set search_path = ''
as $$
  select greatest(1, ceil(char_length(regexp_replace(coalesce(p_html, ''), '<[^>]*>', '', 'g')) / 1100.0))::integer;
$$;

-- Listing with optional category and kind filters.
create or replace function public.blog_feed(
  p_locale   public.app_locale,
  p_category text default null,
  p_kind     public.post_kind default null,
  p_limit    integer default 9,
  p_offset   integer default 0
)
returns table (
  post_id         uuid,
  title           text,
  slug            text,
  excerpt         text,
  cover_path      text,
  published_at    timestamptz,
  category_name   text,
  category_slug   text,
  kind            public.post_kind,
  is_featured     boolean,
  reading_minutes integer,
  total_count     bigint
)
language sql
stable
security invoker
set search_path = ''
as $$
  select
    p.id,
    t.title,
    t.slug,
    t.excerpt,
    p.cover_path,
    p.published_at,
    case when p_locale = 'es' then c.name_es else c.name_en end,
    case when p_locale = 'es' then c.slug_es else c.slug_en end,
    p.kind,
    p.is_featured,
    public.reading_minutes(t.content),
    count(*) over ()
  from public.posts p
  join public.post_translations t on t.post_id = p.id and t.locale = p_locale
  left join public.post_categories c on c.id = p.category_id
  where public.post_is_visible(p.status, p.published_at)
    and (p_category is null or c.slug_en = p_category or c.slug_es = p_category)
    and (p_kind is null or p.kind = p_kind)
  order by p.published_at desc, p.id
  limit least(greatest(p_limit, 1), 100)
  offset greatest(p_offset, 0);
$$;

-- Single post (same rules as blog_post) with the new fields.
create or replace function public.blog_article(p_locale public.app_locale, p_slug text)
returns table (
  post_id         uuid,
  title           text,
  slug            text,
  excerpt         text,
  content         text,
  cover_path      text,
  published_at    timestamptz,
  updated_at      timestamptz,
  category_name   text,
  category_slug   text,
  slugs           jsonb,
  kind            public.post_kind,
  source_url      text,
  reading_minutes integer
)
language sql
stable
security invoker
set search_path = ''
as $$
  select
    b.post_id, b.title, b.slug, b.excerpt, b.content, b.cover_path, b.published_at, b.updated_at,
    b.category_name, b.category_slug, b.slugs,
    p.kind, p.source_url, public.reading_minutes(b.content)
  from public.blog_post(p_locale, p_slug) b
  join public.posts p on p.id = b.post_id;
$$;

grant execute on function public.reading_minutes(text) to anon, authenticated;
grant execute on function public.blog_feed(public.app_locale, text, public.post_kind, integer, integer) to anon, authenticated;
grant execute on function public.blog_article(public.app_locale, text) to anon, authenticated;

-- Save with the new fields. Featuring a post un-features the previous one.
create or replace function public.admin_save_post_v2(
  p_status       public.post_status,
  p_translations jsonb,
  p_id           uuid default null,
  p_published_at timestamptz default null,
  p_category_id  uuid default null,
  p_kind         public.post_kind default 'article',
  p_featured     boolean default false,
  p_source_url   text default null
)
returns uuid
language plpgsql
volatile
security invoker
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if p_featured then
    update public.posts set is_featured = false
     where is_featured and (p_id is null or id <> p_id);
  end if;

  v_id := public.admin_save_post(p_status, p_translations, p_id, p_published_at, p_category_id);

  update public.posts
     set kind = p_kind,
         is_featured = p_featured,
         source_url = nullif(trim(p_source_url), '')
   where id = v_id;
  return v_id;
end;
$$;

revoke all on function public.admin_save_post_v2(public.post_status, jsonb, uuid, timestamptz, uuid, public.post_kind, boolean, text) from public, anon;
grant execute on function public.admin_save_post_v2(public.post_status, jsonb, uuid, timestamptz, uuid, public.post_kind, boolean, text) to authenticated;

-- -----------------------------------------------------------------------------
