-- -----------------------------------------------------------------------------
-- Migration: 20261015000200_remove_blog.sql
-- -----------------------------------------------------------------------------

-- Element — remove the blog.
--
-- The public blog was replaced by the IRS updates page (read from irs.gov, no
-- database), so posts, their translations and categories, the blog functions,
-- the scheduled-publishing job and the cover bucket policy are dropped.
--
-- The newsletter stays: it now emails an IRS update, so newsletter_sends keeps
-- its history but references the update by its irs.gov slug instead of a post.
--
-- Audit log entries about posts are kept (they are history, not blog data).

-- 1) Newsletter sends: post_id -> update_slug ---------------------------------
alter table public.newsletter_sends add column if not exists update_slug text
  check (update_slug is null or update_slug ~ '^[a-z0-9-]{1,300}$');
drop index if exists public.newsletter_sends_post_idx;
alter table public.newsletter_sends drop column if exists post_id;
create index if not exists newsletter_sends_update_idx on public.newsletter_sends (update_slug, created_at desc);

-- 2) Scheduled publishing job --------------------------------------------------
select cron.unschedule(jobid) from cron.job where jobname = 'publish-scheduled-posts';

-- 3) Functions (every overload) ------------------------------------------------
do $$
declare
  fn regprocedure;
begin
  for fn in
    select p.oid::regprocedure
      from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
       and p.proname in (
         'publish_due_posts', 'post_is_visible', 'reading_minutes',
         'blog_list', 'blog_post', 'blog_categories', 'blog_sitemap', 'blog_feed', 'blog_article',
         'admin_save_post', 'admin_save_post_v2'
       )
  loop
    execute format('drop function %s', fn);
  end loop;
end
$$;

-- 4) Tables and types ------------------------------------------------------------
drop table if exists public.post_translations;
drop table if exists public.posts;
drop table if exists public.post_categories;
drop type if exists public.post_kind;
drop type if exists public.post_status;

-- 5) Cover images ----------------------------------------------------------------
drop policy if exists blog_covers_objects_select on storage.objects;

-- Supabase does not allow deleting stored files with SQL. An empty bucket is
-- removed here; if covers were uploaded, delete the "blog-covers" bucket from
-- the dashboard (Storage) instead.
do $$
begin
  delete from storage.buckets where id = 'blog-covers';
exception when others then
  raise notice 'blog-covers bucket not removed (%). Delete it from Storage in the dashboard.', sqlerrm;
end
$$;

-- -----------------------------------------------------------------------------
-- Migration: 20261015000300_audit_without_blog.sql
-- -----------------------------------------------------------------------------

-- Element — audit search without the blog tables.
--
-- admin_search_audit looked up post titles in public.post_translations and
-- public.post_categories, which 20261015000200_remove_blog dropped; plpgsql
-- does not record that dependency, so the function failed at run time (admin
-- overview and audit log). Old post entries now show the title stored in their
-- metadata, and newsletter sends of IRS updates show the update title.
-- create or replace keeps the existing grants.

create or replace function public.admin_search_audit(
  p_q       text default null,
  p_action  text default null,
  p_actor   text default null,
  p_subject uuid default null,
  p_from    date default null,
  p_to      date default null,
  p_limit   integer default 50,
  p_offset  integer default 0
)
returns table (
  id bigint,
  created_at timestamptz,
  action text,
  actor_id uuid,
  actor_email text,
  actor_name text,
  target_type text,
  target_id text,
  target_label text,
  metadata jsonb,
  ip inet,
  user_agent text,
  total_count bigint
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := case when nullif(trim(p_q), '') is null then null else '%' || public.like_escape(trim(p_q)) || '%' end;
  v_actor text := case when nullif(trim(p_actor), '') is null then null else '%' || public.like_escape(trim(p_actor)) || '%' end;
  v_action text := case when nullif(trim(p_action), '') is null then null else public.like_escape(trim(p_action)) || '%' end;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return query
  with rows as (
    select
      a.*,
      au.email::text as actor_email,
      ap.full_name as actor_name,
      case a.target_type
        when 'user' then (select tu.email::text from auth.users tu where tu.id::text = a.target_id)
        when 'file' then coalesce((select f.original_name from public.files f where f.id::text = a.target_id), a.metadata ->> 'original_name')
        when 'category' then (select c.name_en || ' / ' || c.name_es from public.file_categories c where c.id::text = a.target_id)
        when 'post' then a.metadata ->> 'title'
        when 'post_category' then a.metadata ->> 'name'
        when 'update' then a.metadata ->> 'title'
        when 'contact' then (select cm.subject from public.contact_messages cm where cm.id::text = a.target_id)
        else null
      end as target_label
    from public.audit_logs a
    left join auth.users au on au.id = a.actor_id
    left join public.profiles ap on ap.id = a.actor_id
    where (v_action is null or a.action like v_action)
      and (p_subject is null or a.actor_id = p_subject or (a.target_type = 'user' and a.target_id = p_subject::text)
           or (a.metadata ->> 'owner_id') = p_subject::text)
      and (p_from is null or a.created_at >= (p_from::timestamp at time zone 'America/Bogota'))
      and (p_to is null or a.created_at < ((p_to + 1)::timestamp at time zone 'America/Bogota'))
      and (v_actor is null or au.email ilike v_actor or ap.full_name ilike v_actor)
  )
  select r.id, r.created_at, r.action, r.actor_id, r.actor_email, r.actor_name, r.target_type, r.target_id,
         r.target_label, r.metadata, r.ip, r.user_agent, count(*) over ()::bigint
  from rows r
  where v_q is null
     or r.action ilike v_q
     or r.target_id ilike v_q
     or r.target_label ilike v_q
     or r.actor_email ilike v_q
     or host(r.ip) ilike v_q
     or r.metadata::text ilike v_q
  order by r.created_at desc, r.id desc
  limit least(greatest(p_limit, 1), 50000)
  offset greatest(p_offset, 0);
end;
$$;

-- -----------------------------------------------------------------------------
-- Migration: 20261022000100_intake_forms.sql
-- -----------------------------------------------------------------------------

-- Element — client intake form ("What to bring").
--
-- A signed-in client fills out the intake form, attaches documents and signs it.
-- Everything is written ONLY by the server with the service role after
-- validation (same model as files and contact_messages): there are no client
-- insert/update policies for clients. The owner can read their own submissions;
-- administrators read all of them and mark them reviewed.
--
-- Objects (attachments and signature images) live in the private "files" bucket
-- under intake/<owner>/..., outside the files table, so they do not count toward
-- the storage quota and do not require upload access (can_upload).

-- ---------------------------------------------------------------------------
-- intake_submissions: one row per signed form. `data` holds the answers,
-- validated by the server (src/lib/intake/schema.ts).
-- ---------------------------------------------------------------------------
create table public.intake_submissions (
  id                     uuid primary key default gen_random_uuid(),
  owner_id               uuid not null references public.profiles (id) on delete restrict,
  tax_year               smallint not null check (tax_year between 2000 and 2100),
  locale                 public.app_locale not null default 'en',
  taxpayer_name          text not null check (char_length(taxpayer_name) between 1 and 200),
  filing_status          text not null check (filing_status in ('single', 'mfj', 'mfs', 'hoh', 'qss')),
  data                   jsonb not null,
  signer_name            text not null check (char_length(signer_name) between 1 and 200),
  signature_path         text not null,
  spouse_signer_name     text check (spouse_signer_name is null or char_length(spouse_signer_name) between 1 and 200),
  spouse_signature_path  text,
  signed_at              timestamptz not null default now(),
  signer_ip              inet,
  signer_user_agent      text check (signer_user_agent is null or char_length(signer_user_agent) <= 500),
  status                 text not null default 'new' check (status in ('new', 'reviewed')),
  reviewed_by            uuid references public.profiles (id) on delete set null,
  reviewed_at            timestamptz,
  created_at             timestamptz not null default now(),
  constraint intake_submissions_spouse_consistency check ((spouse_signer_name is null) = (spouse_signature_path is null))
);

create index intake_submissions_owner_idx on public.intake_submissions (owner_id, created_at desc);
create index intake_submissions_status_idx on public.intake_submissions (status, created_at desc);
create index intake_submissions_name_trgm_idx on public.intake_submissions using gin (taxpayer_name extensions.gin_trgm_ops);

-- ---------------------------------------------------------------------------
-- intake_uploads: documents attached to the form. A row is created with a
-- signed upload URL (pending), verified by the server (checksum set), and
-- attached when the form is submitted (submission_id set). Unattached rows
-- expire and are cleaned up by the purge-trash function.
-- ---------------------------------------------------------------------------
create table public.intake_uploads (
  id               uuid primary key default gen_random_uuid(),
  owner_id         uuid not null references public.profiles (id) on delete cascade,
  submission_id    uuid references public.intake_submissions (id) on delete cascade,
  doc_type         text not null check (doc_type in (
                     'id', 'ssn', 'dependents', 'income', 'deductions', 'education',
                     'health', 'prior_return', 'irs_letters', 'business', 'other'
                   )),
  original_name    text not null check (char_length(original_name) between 1 and 255),
  storage_path     text not null unique,
  mime_type        text not null check (mime_type in (
                     'application/pdf',
                     'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
                     'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                     'application/vnd.openxmlformats-officedocument.presentationml.presentation',
                     'image/jpeg',
                     'image/png'
                   )),
  size_bytes       bigint not null check (size_bytes > 0 and size_bytes <= 10485760),
  checksum_sha256  text check (checksum_sha256 is null or checksum_sha256 ~ '^[a-f0-9]{64}$'),
  expires_at       timestamptz not null,
  created_at       timestamptz not null default now()
);

create index intake_uploads_submission_idx on public.intake_uploads (submission_id, created_at);
create index intake_uploads_owner_pending_idx on public.intake_uploads (owner_id) where submission_id is null;
create index intake_uploads_expires_idx on public.intake_uploads (expires_at) where submission_id is null;

-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------
alter table public.intake_submissions enable row level security;
alter table public.intake_uploads     enable row level security;

revoke all on public.intake_submissions, public.intake_uploads from anon;

create policy intake_submissions_select_own on public.intake_submissions
  for select to authenticated
  using (owner_id = (select auth.uid()) and (select public.is_active_user()));

create policy intake_submissions_select_admin on public.intake_submissions
  for select to authenticated
  using ((select public.is_admin()));

create policy intake_submissions_update_admin on public.intake_submissions
  for update to authenticated
  using ((select public.is_admin()))
  with check ((select public.is_admin()));

-- Only attached documents are visible to the owner; pending ones are handled by the server.
create policy intake_uploads_select_own on public.intake_uploads
  for select to authenticated
  using (owner_id = (select auth.uid()) and submission_id is not null and (select public.is_active_user()));

create policy intake_uploads_select_admin on public.intake_uploads
  for select to authenticated
  using ((select public.is_admin()));

-- Administrators may only change the review state, never the signed answers.
revoke update on public.intake_submissions from authenticated;
grant update (status, reviewed_by, reviewed_at) on public.intake_submissions to authenticated;

