-- -----------------------------------------------------------------------------
-- Migration: 20261023000200_profile_id_last4.sql
-- -----------------------------------------------------------------------------

-- Element — last four digits of the client's tax ID (SSN, ITIN or EIN).
-- Used to match office records to accounts. Never the full number. Not
-- readable or writable by regular sessions: only admins (through the service
-- role after requireAdmin()) and import scripts set it.

alter table public.profiles
  add column if not exists id_last4 text check (id_last4 is null or id_last4 ~ '^[0-9]{4}$');

create index if not exists profiles_id_last4_idx on public.profiles (id_last4) where id_last4 is not null;

-- No column grant to authenticated: select on profiles is column-restricted
-- (20261007000100), so id_last4 stays hidden from the API. Updates are
-- table-level, so the trigger also blocks non-admins from changing it.
create or replace function public.protect_profile_columns()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.id is distinct from old.id or new.created_at is distinct from old.created_at then
    raise exception 'immutable_column' using errcode = '42501';
  end if;

  if current_user in ('authenticated', 'anon') then
    if not public.is_admin() then
      if new.role is distinct from old.role
         or new.is_active is distinct from old.is_active
         or new.storage_quota_bytes is distinct from old.storage_quota_bytes
         or new.can_upload is distinct from old.can_upload
         or new.id_last4 is distinct from old.id_last4 then
        raise exception 'forbidden_column' using errcode = '42501';
      end if;
    elsif old.id = (select auth.uid())
          and (new.role is distinct from old.role or new.is_active is distinct from old.is_active) then
      raise exception 'self_privilege_change' using errcode = '42501';
    end if;
  end if;

  if old.role = 'admin' and old.is_active
     and (new.role <> 'admin' or not new.is_active)
     and not exists (
       select 1 from public.profiles p
       where p.role = 'admin' and p.is_active and p.id <> old.id
     ) then
    raise exception 'last_admin' using errcode = '42501';
  end if;

  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- Migration: 20261023000300_admin_users_id_last4.sql
-- -----------------------------------------------------------------------------

-- Element — last four digits of the tax ID in the admin user list.
-- Requires 20261023000200_profile_id_last4. The digits are for staff only:
-- clients never see them.
--
-- admin_list_users(): returns id_last4 and finds accounts by it. A search made
-- only of four digits (optionally typed as "***-**-1234" or "xxx-xx-1234")
-- matches id_last4 exactly, in addition to the usual name/email match.

drop function if exists public.admin_list_users(text, text, text, text, text, integer, integer, uuid, text);

create function public.admin_list_users(
  p_search text default null,
  p_status text default null,   -- 'active' | 'inactive' | 'pending'
  p_role   text default null,   -- 'user' | 'admin'
  p_sort   text default 'created_at',
  p_dir    text default 'desc',
  p_limit  integer default 20,
  p_offset integer default 0,
  p_id     uuid default null,
  p_upload text default null    -- 'yes' | 'no'
)
returns table (
  id uuid,
  email text,
  full_name text,
  role public.user_role,
  is_active boolean,
  preferred_locale public.app_locale,
  storage_quota_bytes bigint,
  used_bytes bigint,
  file_count bigint,
  created_at timestamptz,
  last_sign_in_at timestamptz,
  invitation_pending boolean,
  has_mfa boolean,
  can_upload boolean,
  id_last4 text,
  total_count bigint
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_pattern text := case when nullif(trim(p_search), '') is null then null
                         else '%' || public.like_escape(trim(p_search)) || '%' end;
  v_last4   text := case when trim(coalesce(p_search, '')) ~ '^[\s*xX•-]*[0-9]{4}$'
                         then right(regexp_replace(p_search, '[^0-9]', '', 'g'), 4) end;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return query
  with base as (
    select
      p.id,
      u.email::text as email,
      p.full_name,
      p.role,
      p.is_active,
      p.preferred_locale,
      p.storage_quota_bytes,
      coalesce((select sum(f.size_bytes) from public.files f where f.owner_id = p.id and f.deleted_at is null), 0)::bigint as used_bytes,
      (select count(*) from public.files f where f.owner_id = p.id and f.deleted_at is null)::bigint as file_count,
      p.created_at,
      u.last_sign_in_at,
      (u.email_confirmed_at is null) as invitation_pending,
      exists (select 1 from auth.mfa_factors m where m.user_id = p.id and m.status = 'verified') as has_mfa,
      p.can_upload,
      p.id_last4
    from public.profiles p
    join auth.users u on u.id = p.id
    where (p_id is null or p.id = p_id)
      and (v_pattern is null
           or p.full_name ilike v_pattern
           or u.email ilike v_pattern
           or (v_last4 is not null and p.id_last4 = v_last4))
      and (p_status is null
           or (p_status = 'active' and p.is_active and u.email_confirmed_at is not null)
           or (p_status = 'inactive' and not p.is_active)
           or (p_status = 'pending' and u.email_confirmed_at is null))
      and (p_role is null or p.role::text = p_role)
      and (p_upload is null or (p_upload = 'yes') = p.can_upload)
  )
  select b.*, count(*) over ()::bigint
  from base b
  order by
    case when p_sort = 'full_name' and p_dir = 'asc' then lower(b.full_name) end asc,
    case when p_sort = 'full_name' and p_dir = 'desc' then lower(b.full_name) end desc,
    case when p_sort = 'email' and p_dir = 'asc' then b.email end asc,
    case when p_sort = 'email' and p_dir = 'desc' then b.email end desc,
    case when p_sort = 'last_sign_in_at' and p_dir = 'asc' then b.last_sign_in_at end asc nulls first,
    case when p_sort = 'last_sign_in_at' and p_dir = 'desc' then b.last_sign_in_at end desc nulls last,
    case when p_sort = 'used_bytes' and p_dir = 'asc' then b.used_bytes end asc,
    case when p_sort = 'used_bytes' and p_dir = 'desc' then b.used_bytes end desc,
    case when p_sort = 'created_at' and p_dir = 'asc' then b.created_at end asc,
    b.created_at desc,
    b.id
  limit least(greatest(p_limit, 1), 50000)
  offset greatest(p_offset, 0);
end;
$$;

revoke all on function public.admin_list_users(text, text, text, text, text, integer, integer, uuid, text) from public, anon;
grant execute on function public.admin_list_users(text, text, text, text, text, integer, integer, uuid, text) to authenticated, service_role;

-- Clients must not read their own digits: remove the helper an earlier version
-- of this migration created.
drop function if exists public.my_id_last4();

-- -----------------------------------------------------------------------------
-- Migration: 20261026000100_public_intake.sql
-- -----------------------------------------------------------------------------

-- Element — public intake form. Anyone can fill out the New Client Package
-- without an account; staff then assign each form to a client account (an
-- existing one, usually the one that uses the email typed in the form, or a new
-- one invited with that email).
--
-- Anonymous visitors are identified only by a signed draft token issued with
-- the page (src/lib/security/form-token.ts): their pending documents carry the
-- draft id instead of an owner, and a submission records it so a draft can be
-- submitted only once. Everything is still written by the server with the
-- service role; no new client policies. Unassigned forms are visible to
-- administrators only (the owner policies match on owner_id).

-- ---------------------------------------------------------------------------
-- intake_submissions
-- ---------------------------------------------------------------------------
alter table public.intake_submissions alter column owner_id drop not null;

alter table public.intake_submissions
  add column if not exists contact_email text check (contact_email is null or char_length(contact_email) <= 254),
  add column if not exists draft_id uuid,
  add column if not exists assigned_by uuid references public.profiles (id) on delete set null,
  add column if not exists assigned_at timestamptz;

update public.intake_submissions
set contact_email = lower(data -> 'taxpayer' ->> 'email')
where contact_email is null;

create unique index if not exists intake_submissions_draft_key on public.intake_submissions (draft_id) where draft_id is not null;
create index if not exists intake_submissions_unassigned_idx on public.intake_submissions (created_at desc) where owner_id is null;
create index if not exists intake_submissions_contact_email_idx on public.intake_submissions (contact_email);

-- ---------------------------------------------------------------------------
-- intake_uploads: a pending document belongs to an account or to a draft;
-- once attached, the submission decides (owner_id follows the assignment).
-- ---------------------------------------------------------------------------
alter table public.intake_uploads alter column owner_id drop not null;
alter table public.intake_uploads add column if not exists draft_id uuid;

alter table public.intake_uploads drop constraint if exists intake_uploads_owner_or_draft;
alter table public.intake_uploads
  add constraint intake_uploads_owner_or_draft
  check (owner_id is not null or draft_id is not null or submission_id is not null);

create index if not exists intake_uploads_draft_pending_idx on public.intake_uploads (draft_id) where submission_id is null;

-- -----------------------------------------------------------------------------
-- Migration: 20261028000100_intake_face_photo.sql
-- -----------------------------------------------------------------------------

-- Element — face photo on the intake form. After signing, the taxpayer takes
-- (or uploads) a photo of their face; the browser checks that it shows one
-- face before the form can be submitted. The JPEG is stored next to the
-- signatures (intake/<owner>/<submission>/face.jpg). Forms submitted before
-- this change have none.

alter table public.intake_submissions
  add column if not exists face_photo_path text;

